window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e2c926fa9d037c42"]={"versions": [{"id": "FIG-e2c926fa9d037c42", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne (entspricht z. B. der Time Domain ID in IEEE 802.1AS / CAN-TSyn / FrTSyn).\n</li><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU bei zweistufiger Synchronisation (Two-Step Sync).\n</li><li><code>syncLossThreshold: TimeValue [0..1]</code>: Schwellwert für Phasendivergenz/Jitter, ab dem ein Synchronisationsverlust detektiert wird.\n</li><li><code>syncLossTimeout: TimeValue</code>: Timeout-Intervall, nach dessen Ablauf ohne gültige Synchronisationsnachricht der Zustand „Sync Loss“ deklariert wird.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master (Grandmaster Clock) des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Synchronisationsnachrichten (Sync-PDUs).\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Bus- bzw. Clustergrenzen hinweg.\n</li><li><strong><code>CommunicationCluster</code></strong> (erbt von <code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>):\n Repräsentiert den physikalischen Bus (CAN, FlexRay, Ethernet). Unterstützt AUTOSAR-Variantenschnittstellen (<code>«atpVariation»</code>).\n<ul class=\"fig-list\"><li>Attribute: <code>baudrate [0..1]</code>, <code>protocolName [0..1]</code>, <code>protocolVersion [0..1]</code>.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts an einen Cluster.\n<ul class=\"fig-list\"><li>Attribut: <code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Physikalisches Steuergerät, beinhaltet allgemeine Kommunikations-, Routing- und Powermanagement-Parameter (u. a. <code>comConfigurationGwTimeBase</code>, <code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li><li><strong><code>GeneralPurposePdu</code></strong> (erbt von <code>Pdu</code>):\n PDU-Container, der spezifisch für zeitbezogene Protokollnachrichten verwendet wird.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Kompositionen innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+master [0..1]</code>: Eine Domäne hat maximal einen aktiven Master-Endpunkt.\n</li><li><code>+slave [0..*]</code>: Beliebig viele Slaves pro Domäne.\n</li><li><code>+gateway [0..*]</code>: Optionale Zeitgateways innerhalb der Domäne.\n</li></ul>\n</li><li><strong>Strukturierte Topologiebeziehungen:</strong>\n<ul class=\"fig-list\"><li><code>+subDomain [0..*]</code>: Hierarchische Schachtelung von Sub-Zeitdomänen (rekursive Komposition auf <code>GlobalTimeDomain</code>).\n</li><li><code>+offsetTimeDomain [0..1]</code>: Verknüpfung zu einer Zeitdomäne mit festem/variablem Offset zur Hauptzeitbasis.\n</li></ul>\n</li><li><strong>Netzwerkanbindung:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> → <code>CommunicationCluster</code> (<code>+communicationCluster [0..*]</code>): Zuordnung der Domäne zu einem oder mehreren physikalischen Netzwerken.\n</li><li><code>GlobalTimeDomain</code> → <code>GeneralPurposePdu</code> (<code>+globalTimePdu [0..1]</code>): Referenz auf die primäre Zeit-PDU.\n</li><li><code>GlobalTimeMaster</code> / <code>GlobalTimeSlave</code> → <code>CommunicationConnector</code> (<code>+communicationConnector [1]</code>): Eindeutige Bindung des Master-/Slave-Endpunkts an ein physisches Businterface.\n</li></ul>\n</li><li><strong>Gateway-Struktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> → <code>GlobalTimeSlave</code> (<code>+slave [1]</code>): Genau ein Ingress-Endpunkt (Zeitaufnahme).\n</li><li><code>GlobalTimeGateway</code> → <code>GlobalTimeMaster</code> (<code>+master [1]</code>): Genau ein Egress-Endpunkt (Zeitausgabe).\n</li><li><code>GlobalTimeGateway</code> → <code>EcuInstance</code> (<code>+host [1]</code>): Feste Zuordnung des Gateways zu einem physischen Host-Steuergerät.\n</li><li><code>EcuInstance</code> → <code>CommunicationConnector</code> (<code>+connector [*]</code>): Komposition der Netzwerkschnittstellen des Host-ECUs.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus den Modellparametern leitet sich folgende BSW-Laufzeitdynamik ab:</p>\n<pre class=\"fig-pre\"><code>[GlobalTimeMaster]             [Physikalischer Bus]              [GlobalTimeSlave]\n        |                               |                                |\n        |--- Sync-PDU (T0) ------------&gt;|                                |\n        |    (Periode: syncPeriod)      |--- Sync-PDU (T0_rx) ----------&gt;|\n        |                               |                                |  (Start followUpTimeoutValue)\n        |--- FollowUp-PDU (T0_precise)-&gt;|                                |\n        |                               |--- FollowUp-PDU --------------&gt;|\n        |                               |                                |  (Offset- &amp; Driftberechnung)\n        |                               |                                |\n        |                               |  x [Sync-PDU fehlt]            |\n        |                               |                                |-- Timer: syncLossTimeout läuft ab\n        |                               |                                |   -&gt; Status: SYNC_LOSS</code></pre>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Zyklus:</strong> <code>GlobalTimeMaster</code> sendet basierend auf <code>syncPeriod</code> periodisch eine Synchronisations-PDU via <code>+globalTimePdu</code>.\n</li><li><strong>Two-Step-Mechanismus:</strong> Bei Controllern mit verzögertem Hardware-Timestamping (z. B. CAN/Ethernet ohne On-the-Fly-Modifikation) triggert die Sync-PDU die Erfassung des präzisen Sendezeitpunkts T_0. Der Master übermittelt diesen Wert anschließend in einer Follow-Up-PDU.\n</li><li><strong>Slave-Überwachung &amp; Abbruchkriterien:</strong>\n<ul class=\"fig-list\"><li>Trifft die Follow-Up-PDU nicht innerhalb von <code>followUpTimeoutValue</code> am Slave ein, wird der Synchronisationszyklus verworfen.\n</li><li>Bleiben Sync-PDUs länger als <code>syncLossTimeout</code> aus oder überschreitet die lokale Zeitabweichung <code>syncLossThreshold</code>, meldet der Slave intern Synchronisationsverlust (BSW-Zustandswechsel via StbM / Dem-Event).\n</li></ul>\n</li><li><strong>Gateway-Propagation:</strong> Das <code>GlobalTimeGateway</code> empfängt über seinen <code>GlobalTimeSlave</code> die Masterzeit des Quell-Clusters, berechnet die Gateway-interne Latenz (Verarbeitungszeit auf der <code>EcuInstance</code>) und fungiert über seinen <code>GlobalTimeMaster</code> als Zeiterzeuger für den Ziel-Cluster.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-51e2aacff1c22971", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Zustandswechsel und Ereignisse der Zeitdomäne.\n</li><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne.\n</li><li><code>syncLossThreshold: TimeValue [0..1]</code>: Schwellwert für Phasendivergenz/Jitter, ab dem ein Synchronisationsverlust detektiert wird.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die sofortige Wiederaufnahme der Synchronisationsaussendung nach Aufwachen oder Reinitialisierung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft, ab dem Sonderbehandlungen (z. B. Filterung oder Neusynchronisation) greifen.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für aufeinanderfolgende Zyklen zur Bestätigung/Heilung nach einem detektierten Zeitsprung.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Bus- bzw. Clustergrenzen hinweg.\n</li><li><strong><code>CommunicationCluster</code></strong> (erbt von <code>FibexElement</code>, Stereotyp <code>«atpVariation»</code>):\n Repräsentiert den physikalischen Bus mit Attributen <code>baudrate [0..1]</code>, <code>protocolName [0..1]</code>, <code>protocolVersion [0..1]</code>.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts an einen Cluster mit Attribut <code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>.\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Steuergerät mit Parametern: <code>comConfigurationGwTimeBase: TimeValue [0..1]</code>, <code>comConfigurationRxTimeBase: TimeValue [0..1]</code>, <code>comConfigurationTxTimeBase: TimeValue [0..1]</code>, <code>comEnableMDTForCyclicTransmission: Boolean [0..1]</code>, <code>diagnosticAddress: Integer [0..1]</code>, <code>ethSwitchPortGroupDerivation: Boolean [0..1]</code>, <code>pncPrepareSleepTimer: TimeValue [0..1]</code>, <code>pnResetTime: TimeValue [0..1]</code>, <code>sleepModeSupported: Boolean</code>, <code>v2xSupported: V2xSupportEnum [0..1]</code>, <code>wakeUpOverBusSupported: Boolean</code>.\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Kompositionen innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+master [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Beliebig viele Slaves pro Domäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+subDomain [0..*]</code>: Hierarchische Schachtelung von Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProps [0..1]</code>: Spezifische Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+offsetTimeDomain [0..1]</code>: Optionale Referenz auf eine Offset-Zeitdomäne.\n</li><li><code>+globalTimePduTriggering [0..1]</code>: Zuordnung zu einer PDU-Triggerung (<code>PduTriggering</code>).\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert genau einen <code>+master [1]</code> und genau einen <code>+slave [1]</code>.\n</li><li><code>GlobalTimeGateway</code> referenziert das Host-Steuergerät (<code>+host [1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>EcuInstance</code> aggregiert per Komposition <code>+connector [*] -&gt; CommunicationConnector</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit konfigurierter <code>domainId</code> und optionalen <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuweisung der PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; nach Neustarts/Aufwachen kann die Aussendung nach Ablauf von <code>immediateResumeTime</code> direkt einsetzen.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> prüft eingehende Zeitstempel gegen <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code>. Treten unzulässige Sprünge auf, erfolgt erst nach Ablauf des <code>timeLeapHealingCounter</code> wieder eine reguläre Nachführung der lokalen Uhr.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bei Ausbleiben von Synchronisationsnachrichten über <code>syncLossTimeout</code> oder Überschreitung von <code>syncLossThreshold</code> unter Berücksichtigung von <code>debounceTime</code> wird Synchronisationsverlust gemeldet.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-17abf8f3d1a8981c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Ereignisse und Zustandswechsel.\n</li><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für Bestätigungszyklen nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Busgrenzen hinweg.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts mit Attribut <code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>.\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Steuergerät mit Parametern: <code>comConfigurationGwTimeBase: TimeValue [0..1]</code>, <code>comConfigurationRxTimeBase: TimeValue [0..1]</code>, <code>comConfigurationTxTimeBase: TimeValue [0..1]</code>, <code>comEnableMDTForCyclicTransmission: Boolean [0..1]</code>, <code>diagnosticAddress: Integer [0..1]</code>, <code>ethSwitchPortGroupDerivation: Boolean [0..1]</code>, <code>pncPrepareSleepTimer: TimeValue [0..1]</code>, <code>pnResetTime: TimeValue [0..1]</code>, <code>sleepModeSupported: Boolean</code>, <code>v2xSupported: V2xSupportEnum [0..1]</code>, <code>wakeUpOverBusSupported: Boolean</code>.\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Korrekturparameter für Uhrphasen- und Ratenanpassung.\n<ul class=\"fig-list\"><li><code>offsetCorrectionAdaptionInterval: TimeValue [0..1]</code>: Anpassungsintervall für die Offset-Korrektur.\n</li><li><code>offsetCorrectionJumpThreshold: TimeValue [0..1]</code>: Schwellwert für sprunghafte Offset-Korrekturen.\n</li><li><code>rateCorrectionMeasurementDuration: TimeValue [0..1]</code>: Messdauer zur Bestimmung der Ratenabweichung (Drift).\n</li><li><code>rateCorrectionsPerMeasurementDuration: PositiveInteger [0..1]</code>: Anzahl der Ratenkorrekturschritte je Messdauer.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Variante Kompositionen (<code>«atpVariation»</code>) innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeMaster [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Slaves der Zeitdomäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+globalTimeSubDomain [0..*]</code>: Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProperty [0..1]</code>: Spezifische Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Weitere Kompositionen und Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeCorrectionProps [0..1]</code>: Komposition zu <code>GlobalTimeCorrectionProps</code>.\n</li><li><code>+pduTriggering [0..1]</code> (<code>«atpVariation»</code>): Zuordnung zu einer PDU-Triggerung.\n</li><li><code>+offsetTimeDomain [0..1]</code>: Optionale Referenz auf eine Offset-Zeitdomäne.\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert genau einen <code>+master [1]</code> und genau einen <code>+slave [1]</code>.\n</li><li><code>GlobalTimeGateway</code> ist an das Host-Steuergerät angebunden (<code>+host [1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>EcuInstance</code> aggregiert Konnektoren (<code>+connector [*] -&gt; CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code> und <code>GlobalTimeCorrectionProps</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuordnung der varianten PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Uhrenkorrektur:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; nach Reinitialisierung kann <code>immediateResumeTime</code> greifen.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> überwacht Zeitsprünge über <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> mit Bestätigung über <code>timeLeapHealingCounter</code>.\n</li><li>Unter Verwendung von <code>GlobalTimeCorrectionProps</code> werden Offset-Sprünge unterhalb von <code>offsetCorrectionJumpThreshold</code> über das Intervall <code>offsetCorrectionAdaptionInterval</code> eingeschlichen; Driften werden über die Dauer <code>rateCorrectionMeasurementDuration</code> mit <code>rateCorrectionsPerMeasurementDuration</code> Schritten kompensiert.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bleibt die Synchronisation über <code>syncLossTimeout</code> hinaus aus, wird unter Berücksichtigung von <code>debounceTime</code> der Synchronisationsverlust deklariert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-9d3ff3647d0c2574", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Ereignisse und Zustandswechsel.\n</li><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für Bestätigungszyklen nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Busgrenzen hinweg.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Legt fest, ob der Konnektor als Weckquelle für das Steuergerät fungiert.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Routing-Typ für Partial Networking.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Steuergerät mit Parametern: <code>comConfigurationGwTimeBase: TimeValue [0..1]</code>, <code>comConfigurationRxTimeBase: TimeValue [0..1]</code>, <code>comConfigurationTxTimeBase: TimeValue [0..1]</code>, <code>comEnableMDTForCyclicTransmission: Boolean [0..1]</code>, <code>ethSwitchPortGroupDerivation: Boolean [0..1]</code>, <code>pncPrepareSleepTimer: TimeValue [0..1]</code>, <code>pncSynchronousWakeup: Boolean [0..1]</code>, <code>pnResetTime: TimeValue [0..1]</code>, <code>sleepModeSupported: Boolean</code>, <code>v2xSupported: V2xSupportEnum [0..1]</code>, <code>wakeUpOverBusSupported: Boolean</code>.\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Korrekturparameter für Uhrphasen- und Ratenanpassung mit Attributen <code>offsetCorrectionAdaptionInterval</code>, <code>offsetCorrectionJumpThreshold</code>, <code>rateCorrectionMeasurementDuration</code> und <code>rateCorrectionsPerMeasurementDuration</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Variante Kompositionen (<code>«atpVariation»</code>) innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeMaster [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Slaves der Zeitdomäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+globalTimeSubDomain [0..*]</code>: Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProperty [0..1]</code>: Spezifische Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Weitere Kompositionen und Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeCorrectionProps [0..1]</code>: Komposition zu <code>GlobalTimeCorrectionProps</code>.\n</li><li><code>+pduTriggering [0..1]</code> (<code>«atpVariation»</code>): Zuordnung zu einer PDU-Triggerung.\n</li><li><code>+offsetTimeDomain [0..1]</code> (<code>«atpVariation»</code>): Variante Assoziation auf eine Offset-Zeitdomäne.\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert genau einen <code>+master [1]</code> und genau einen <code>+slave [1]</code>.\n</li><li><code>GlobalTimeGateway</code> ist an das Host-Steuergerät angebunden (<code>+host [1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>EcuInstance</code> aggregiert Konnektoren (<code>+connector [*]</code> mit <code>«atpVariation»</code> auf <code>CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code> und <code>GlobalTimeCorrectionProps</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuordnung der varianten PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Uhrenkorrektur:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; nach Reinitialisierung kann <code>immediateResumeTime</code> greifen.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> überwacht Zeitsprünge über <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> mit Bestätigung über <code>timeLeapHealingCounter</code>.\n</li><li>Unter Verwendung von <code>GlobalTimeCorrectionProps</code> werden Offset-Sprünge unterhalb von <code>offsetCorrectionJumpThreshold</code> über das Intervall <code>offsetCorrectionAdaptionInterval</code> eingeschlichen; Driften werden über die Dauer <code>rateCorrectionMeasurementDuration</code> mit <code>rateCorrectionsPerMeasurementDuration</code> Schritten kompensiert.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bleibt die Synchronisation über <code>syncLossTimeout</code> hinaus aus, wird unter Berücksichtigung von <code>debounceTime</code> der Synchronisationsverlust deklariert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c7dcf7fc04af5af1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Ereignisse und Zustandswechsel.\n</li><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für Bestätigungszyklen nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Busgrenzen hinweg.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Kennzeichnet die Weckquellenfunktion.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert dynamisches Mapping von Partial Network Clusters auf Kanäle.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Routing-Typ für Partial Networking.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Physikalisches Steuergerät ohne spezifische Parameterattribute in dieser Ansicht.\n</li><li><strong><code>NetworkSegmentIdentification</code></strong>:\n Identifiziert ein Netzwerksegment.\n<ul class=\"fig-list\"><li><code>networkSegmentId: PositiveInteger [0..1]</code>: Eindeutige Kennung des Segments.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Korrekturparameter für Uhrphasen- und Ratenanpassung mit Attributen <code>offsetCorrectionAdaptionInterval</code>, <code>offsetCorrectionJumpThreshold</code>, <code>rateCorrectionMeasurementDuration</code> und <code>rateCorrectionsPerMeasurementDuration</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Variante Kompositionen (<code>«atpVariation»</code>) innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeMaster [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Slaves der Zeitdomäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+globalTimeSubDomain [0..*]</code>: Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProperty [0..1]</code>: Spezifische Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Weitere Kompositionen und Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+networkSegmentId [0..1]</code>: Komposition zu <code>NetworkSegmentIdentification</code>.\n</li><li><code>+globalTimeCorrectionProps [0..1]</code>: Komposition zu <code>GlobalTimeCorrectionProps</code>.\n</li><li><code>+pduTriggering [0..1]</code> (<code>«atpVariation»</code>): Zuordnung zu einer PDU-Triggerung.\n</li><li><code>+offsetTimeDomain [0..1]</code>: Optionale Assoziation auf eine Offset-Zeitdomäne.\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert genau einen <code>+master [1]</code> und genau einen <code>+slave [1]</code>.\n</li><li><code>GlobalTimeGateway</code> ist an das Host-Steuergerät angebunden (<code>+host [1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>EcuInstance</code> aggregiert Konnektoren (<code>+connector [*]</code> mit <code>«atpVariation»</code> auf <code>CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code> und <code>GlobalTimeCorrectionProps</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuordnung der varianten PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Uhrenkorrektur:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; nach Reinitialisierung kann <code>immediateResumeTime</code> greifen.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> überwacht Zeitsprünge über <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> mit Bestätigung über <code>timeLeapHealingCounter</code>.\n</li><li>Unter Verwendung von <code>GlobalTimeCorrectionProps</code> werden Offset-Sprünge unterhalb von <code>offsetCorrectionJumpThreshold</code> über das Intervall <code>offsetCorrectionAdaptionInterval</code> eingeschlichen; Driften werden über die Dauer <code>rateCorrectionMeasurementDuration</code> mit <code>rateCorrectionsPerMeasurementDuration</code> Schritten kompensiert.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bleibt die Synchronisation über <code>syncLossTimeout</code> hinaus aus, wird unter Berücksichtigung von <code>debounceTime</code> der Synchronisationsverlust deklariert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-745b7fdd02641762", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Ereignisse und Zustandswechsel.\n</li><li><code>domainId: PositiveInteger</code>: Eindeutiger Identifikator der Zeitdomäne.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>icvSecured: GlobalTimeIcvSupportEnum [0..1]</code>: Gibt an, ob Integritätsprüfwerte (ICV) zur Absicherung der Zeit-PDUs unterstützt werden.\n</li><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean</code>: Kennzeichnet den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue</code>: Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Verifikationsmodus für empfangene Integritätsprüfwerte.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für Bestätigungszyklen nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Busgrenzen hinweg.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Kennzeichnet die Weckquellenfunktion.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert dynamisches Mapping von Partial Network Clusters.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Maske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Routing-Typ für Partial Networking.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Physikalisches Steuergerät.\n</li><li><strong><code>NetworkSegmentIdentification</code></strong>:\n<ul class=\"fig-list\"><li><code>networkSegmentId: PositiveInteger [0..1]</code>: Eindeutige Kennung des Netzwerksegments.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Korrekturparameter für Uhrphasen- und Ratenanpassung mit Attributen <code>offsetCorrectionAdaptionInterval</code>, <code>offsetCorrectionJumpThreshold</code>, <code>rateCorrectionMeasurementDuration</code> und <code>rateCorrectionsPerMeasurementDuration</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeIcvSupportEnum</code></strong>:\n Wertebereich: <code>icvSupported</code>, <code>icvNotSupported</code>.\n</li><li><strong><code>GlobalTimeIcvVerificationEnum</code></strong>:\n Wertebereich: <code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code>, <code>icvOptional</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Variante und splitbare Kompositionen (<code>«atpVariation,atpSplitable»</code>) innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeMaster [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Slaves der Zeitdomäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+globalTimeSubDomain [0..*]</code>: Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProperty [0..1]</code>: Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Weitere Kompositionen und Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+networkSegmentId [0..1]</code>: Komposition zu <code>NetworkSegmentIdentification</code>.\n</li><li><code>+globalTimeCorrectionProps [0..1]</code>: Komposition zu <code>GlobalTimeCorrectionProps</code>.\n</li><li><code>+pduTriggering [0..1]</code> (<code>«atpVariation,atpSplitable»</code>): PDU-Triggerung.\n</li><li><code>+offsetTimeDomain [0..1]</code>: Optionale Assoziation auf eine Offset-Zeitdomäne.\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert genau einen <code>+master [1]</code> und genau einen <code>+slave [1]</code>.\n</li><li><code>GlobalTimeGateway</code> ist an das Host-Steuergerät angebunden (<code>+host [1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert genau einen <code>+communicationConnector [1]</code>.\n</li><li><code>EcuInstance</code> aggregiert Konnektoren (<code>+connector [*]</code> mit <code>«atpVariation,atpSplitable»</code> auf <code>CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code>, <code>GlobalTimeCorrectionProps</code> und <code>NetworkSegmentIdentification</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuweisung der PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Sicherheitsabsicherung:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; falls <code>icvSecured == icvSupported</code>, wird die Nachricht mit einem Integritätsprüfwert (Integrity Check Value) abgesichert.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> prüft eingehende Nachrichten gemäß <code>icvVerification</code> (<code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code> oder <code>icvOptional</code>). Bei erfolgreicher Prüfung und Plausibilisierung gegen <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> (unter Berücksichtigung von <code>timeLeapHealingCounter</code>) wird die lokale Uhr korrigiert.\n</li><li>Phasen- und Frequenzanpassungen erfolgen parametrisiert über <code>GlobalTimeCorrectionProps</code>.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bei Ausfall der Synchronisationsnachrichten über <code>syncLossTimeout</code> hinaus wird unter Berücksichtigung von <code>debounceTime</code> Synchronisationsverlust signalisiert. Nachrichten mit fehlerhaftem ICV werden entsprechend der Konfiguration verworfen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-8842564e4be0cbb6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code> und <code>UploadableDesignElement</code>):\n Repräsentiert eine logisch zusammenhängende globale Zeitbasis.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Ereignisse und Zustandswechsel.\n</li><li><code>domainId: PositiveInteger [0..1]</code>: Optionaler Identifikator der Zeitdomäne.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Intervall bis zur Deklaration von Synchronisationsverlust.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Definiert die zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>icvSecured: GlobalTimeIcvSupportEnum [0..1]</code>: Kennzeichnung der ICV-Unterstützung.\n</li><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean [0..1]</code>: Kennzeichnet optional den Root-Master des Gesamtfahrzeugs.\n</li><li><code>syncPeriod: TimeValue [0..1]</code>: Optionale Zykluszeit für die periodische Aussendung von Sync-PDUs.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, synchronisiert ihre lokale Uhr auf die Master-Zeitbasis.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Wartezeit auf eine zugehörige Follow-Up-PDU.\n</li><li><code>icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Verifikationsmodus für empfangene Integritätsprüfwerte.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zähler für Bestätigungszyklen nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Brückenknoten zur Weiterleitung und Synchronisation von Zeitbasen über Busgrenzen hinweg.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Netzwerkinterface eines Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Kennzeichnet die Weckquellenfunktion.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert dynamisches Mapping von Partial Network Clusters.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Maske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Routing-Typ für Partial Networking.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Physikalisches Steuergerät.\n</li><li><strong><code>NetworkSegmentIdentification</code></strong>:\n<ul class=\"fig-list\"><li><code>networkSegmentId: PositiveInteger [0..1]</code>: Eindeutige Kennung des Netzwerksegments.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Trigger-Entität für PDUs auf einem Kommunikationspfad.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für domänenspezifische Zusatzparameter.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Korrekturparameter für Uhrphasen- und Ratenanpassung mit Attributen <code>offsetCorrectionAdaptionInterval</code>, <code>offsetCorrectionJumpThreshold</code>, <code>rateCorrectionMeasurementDuration</code> und <code>rateCorrectionsPerMeasurementDuration</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeIcvSupportEnum</code></strong>:\n Wertebereich: <code>icvSupported</code>, <code>icvNotSupported</code>.\n</li><li><strong><code>GlobalTimeIcvVerificationEnum</code></strong>:\n Wertebereich: <code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code>, <code>icvOptional</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen und Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Variante und splitbare Kompositionen (<code>«atpVariation,atpSplitable»</code>) innerhalb <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+globalTimeMaster [0..1]</code>: Maximal ein aktiver Master pro Zeitdomäne.\n</li><li><code>+slave [0..*]</code>: Slaves der Zeitdomäne.\n</li><li><code>+gateway [0..*]</code>: Zeitgateways innerhalb der Domäne.\n</li><li><code>+globalTimeSubDomain [0..*]</code>: Sub-Zeitdomänen.\n</li><li><code>+globalTimeDomainProperty [0..1]</code>: Domäneneigenschaften über <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><strong>Weitere Kompositionen und Assoziationen von <code>GlobalTimeDomain</code>:</strong>\n<ul class=\"fig-list\"><li><code>+networkSegmentId [0..1]</code>: Komposition zu <code>NetworkSegmentIdentification</code>.\n</li><li><code>+globalTimeCorrectionProps [0..1]</code>: Komposition zu <code>GlobalTimeCorrectionProps</code>.\n</li><li><code>+pduTriggering [0..1]</code> (<code>«atpVariation,atpSplitable»</code>): PDU-Triggerung.\n</li><li><code>+offsetTimeDomain [0..1]</code>: Optionale Assoziation auf eine Offset-Zeitdomäne.\n</li></ul>\n</li><li><strong>Kopplung der Rollen und Infrastruktur:</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeGateway</code> referenziert optional <code>+master [0..1]</code> und optional <code>+slave [0..1]</code>.\n</li><li><code>GlobalTimeGateway</code> referenziert optional ein Host-Steuergerät (<code>+host [0..1] -&gt; EcuInstance</code>).\n</li><li><code>GlobalTimeMaster</code> referenziert optional einen <code>+communicationConnector [0..1]</code>.\n</li><li><code>GlobalTimeSlave</code> referenziert optional einen <code>+communicationConnector [0..1]</code>.\n</li><li><code>EcuInstance</code> aggregiert Konnektoren (<code>+connector [*]</code> mit <code>«atpVariation,atpSplitable»</code> auf <code>CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code>, <code>GlobalTimeCorrectionProps</code> und <code>NetworkSegmentIdentification</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuweisung der PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Sicherheitsabsicherung:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; falls <code>icvSecured == icvSupported</code>, wird die Nachricht mit einem Integritätsprüfwert (Integrity Check Value) abgesichert.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> prüft eingehende Nachrichten gemäß <code>icvVerification</code> (<code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code> oder <code>icvOptional</code>). Bei erfolgreicher Prüfung und Plausibilisierung gegen <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> (unter Berücksichtigung von <code>timeLeapHealingCounter</code>) wird die lokale Uhr korrigiert.\n</li><li>Phasen- und Frequenzanpassungen erfolgen parametrisiert über <code>GlobalTimeCorrectionProps</code>.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bei Ausfall der Synchronisationsnachrichten über <code>syncLossTimeout</code> hinaus wird unter Berücksichtigung von <code>debounceTime</code> Synchronisationsverlust signalisiert. Nachrichten mit fehlerhaftem ICV werden entsprechend der Konfiguration verworfen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-4a1b82f4a506c077", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>, <code>UploadableDesignElement</code>):\n Zentrale Entität einer logischen Zeitdomäne.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Zustandswechsel und Ereignisse.\n</li><li><code>domainId: PositiveInteger [0..1]</code>: Eindeutige Kennung der Zeitdomäne.\n</li><li><code>icvFreshnessValueId: PositiveInteger [0..1]</code>: Identifikator des Frischewerts für ICV-Prüfungen.\n</li><li><code>maxProgressionMismatchThreshold: TimeValue [0..1]</code>: Schwellwert für unzulässige Abweichungen im zeitlichen Fortschritt.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Schwelle bis zum Erkennen eines Synchronisationsverlusts.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>icvSecured: GlobalTimeIcvSupportEnum [0..1]</code>: Status der Integritätsabsicherung (ICV).\n</li><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean [0..1]</code>: Kennzeichnet die Instanz als fahrzeugweiten Master.\n</li><li><code>syncPeriod: TimeValue [0..1]</code>: Zykluszeit für die periodische Aussendung von Synchronisationsnachrichten.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, die auf die Masterzeit synchronisiert wird.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximale Wartezeit auf eine Follow-Up-PDU.\n</li><li><code>icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Modus der ICV-Verifikation.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zählerschwelle zur Entprellung/Heilung nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Leitet Zeitinformationen zwischen Domänen weiter.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Kommunikationsanschluss des Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Bestimmt, ob der Anschluss als Weckquelle dient.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert dynamische Zuordnung von Partial Network Clusters.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Typ des PNC-Gateways.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Steuergeräteinstanz im System.\n</li><li><strong><code>NetworkSegmentIdentification</code></strong>:\n<ul class=\"fig-list\"><li><code>networkSegmentId: PositiveInteger [0..1]</code>: Eindeutige Segmentkennung im Netzwerk.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Triggerung der zur Zeitsynchronisation genutzten PDU.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für clusterspezifische Domäneneigenschaften.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Parameter zur Raten- und Offset-Korrektur.\n<ul class=\"fig-list\"><li><code>offsetCorrectionAdaptionInterval: TimeValue [0..1]</code>: Anpassungsintervall für Offset-Korrekturen.\n</li><li><code>offsetCorrectionJumpThreshold: TimeValue [0..1]</code>: Sprungschwellwert für Offset-Korrekturen.\n</li><li><code>rateCorrectionMeasurementDuration: TimeValue [0..1]</code>: Messdauer für Ratenkorrektur.\n</li><li><code>rateCorrectionsPerMeasurementDuration: PositiveInteger [0..1]</code>: Anzahl der Ratenkorrekturen je Messdauer.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeIcvSupportEnum</code></strong>: <code>icvSupported</code>, <code>icvNotSupported</code>.\n</li><li><strong><code>GlobalTimeIcvVerificationEnum</code></strong>: <code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code>, <code>icvOptional</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen und Kompositionen</h5>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):\n<ul class=\"fig-list\"><li><code>+globalTimeCorrectionProps 0..1</code>: <code>GlobalTimeCorrectionProps</code>\n</li><li><code>+pduTriggering 0..1</code>: <code>PduTriggering</code>\n</li><li><code>+globalTimeSubDomain 0..*</code>: hierarchische Subdomänen (<code>GlobalTimeDomain</code>)\n</li><li><code>+globalTimeDomainProperty 0..1</code>: <code>AbstractGlobalTimeDomainProps</code>\n</li><li><code>+networkSegmentId 0..1</code>: <code>NetworkSegmentIdentification</code>\n</li><li><code>+gateway 0..*</code>: <code>GlobalTimeGateway</code>\n</li><li><code>+globalTimeMaster 0..1</code>: <code>GlobalTimeMaster</code>\n</li><li><code>+slave 0..*</code>: <code>GlobalTimeSlave</code>\n</li></ul>\n</li><li><code>GlobalTimeGateway</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+host 0..1</code> zu <code>EcuInstance</code>\n</li><li>Assoziation <code>+slave 0..1</code> zu <code>GlobalTimeSlave</code>\n</li><li>Assoziation <code>+master 0..1</code> zu <code>GlobalTimeMaster</code>\n</li></ul>\n</li><li><code>GlobalTimeMaster</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector 0..1</code> zu <code>CommunicationConnector</code>\n</li></ul>\n</li><li><code>GlobalTimeSlave</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector 0..1</code> zu <code>CommunicationConnector</code>\n</li></ul>\n</li><li><code>EcuInstance</code> aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):\n<ul class=\"fig-list\"><li><code>+connector *</code>: <code>CommunicationConnector</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code>, <code>GlobalTimeCorrectionProps</code> und <code>NetworkSegmentIdentification</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuweisung der PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Sicherheitsabsicherung:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; falls <code>icvSecured == icvSupported</code>, wird die Nachricht mit einem Integritätsprüfwert (Integrity Check Value) abgesichert.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> prüft eingehende Nachrichten gemäß <code>icvVerification</code> (<code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code> oder <code>icvOptional</code>). Bei erfolgreicher Prüfung und Plausibilisierung gegen <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> (unter Berücksichtigung von <code>timeLeapHealingCounter</code>) wird die lokale Uhr korrigiert.\n</li><li>Phasen- und Frequenzanpassungen erfolgen parametrisiert über <code>GlobalTimeCorrectionProps</code>.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bei Ausfall der Synchronisationsnachrichten über <code>syncLossTimeout</code> hinaus wird unter Berücksichtigung von <code>debounceTime</code> Synchronisationsverlust signalisiert. Nachrichten mit fehlerhaftem ICV werden entsprechend der Konfiguration verworfen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Mapping (Classic Platform):</strong>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> korrespondiert 1:1 mit einer <code>StbMTimeBase</code> im Synchronized Time-Base Manager (<code>StbM</code>).\n</li><li><code>GlobalTimeMaster</code> und <code>GlobalTimeSlave</code> konfigurieren die Busschnittstellenmodule: <code>CanTSyn</code>, <code>FrTSyn</code> oder <code>EthTSyn</code> (z. B. Mapping von <code>domainId</code> auf <code>CanTSynGlobalTimeDomainId</code>).\n</li><li>Das Flag <code>isSystemWideGlobalTimeMaster = true</code> darf im Gesamtsystem systemweit nur an exakt einer Instanz gesetzt sein (<code>TPS_SYST_05007</code>); Verstöße führen zu Synchronisationskonflikten und Multimaster-Kollisionen.\n</li></ul>\n</li><li><strong>Gateway-Realisierung:</strong>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>GlobalTimeGateway</code> erfordert im StbM die Aktivierung des Time-Gateway-Routings (<code>StbMTimeBaseGateway</code>). Entwickler müssen sicherstellen, dass die Latenzkompensation (Ingress-Timestamp bis Egress-Timestamp) im BSW-Stack unterstützt und kalibriert ist.\n</li></ul>\n</li><li><strong>PDU- und Interface-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die referenzierte <code>GeneralPurposePdu</code> (<code>+globalTimePdu</code>) muss im PDU-Router (<code>PduR</code>) für die direkte Weiterleitung an das entsprechende <code>*TSyn</code>-Modul ohne Umweg über den <code>Com</code>-Stack konfiguriert werden.\n</li></ul>\n</li><li><strong>Restriktionen &amp; Validierung:</strong>\n<ul class=\"fig-list\"><li><code>syncLossTimeout</code> muss strikt größer dimensioniert sein als <code>syncPeriod</code>, um transienten Jitter oder Busüberlastungen ohne sofortigen Sync-Verlust abzufangen (typisch: Faktor 2,5 bis 3 × syncPeriod).\n</li><li><code>followUpTimeoutValue</code> muss kleiner als <code>syncPeriod</code> sein, um PDU-Überholungen und Verwechslungen von Messzyklen im Treiber auszuschließen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-719015d57d522355", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-2.0-Metamodell-Klassendiagramm (AUTOSAR System Template, M2-Ebene).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) auf Ebene der System Description (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R4.2.2).\n</li><li><strong>Zweck:</strong> Festlegung der Systemtopologie für zeitsynchrone Netzwerke über verschiedene Kommunikationscluster (CAN, FlexRay, Ethernet/gPTP). Das Modell definiert Zeitdomänen (<code>GlobalTimeDomain</code>), die Rollenverteilung (Master, Slave, Gateway) sowie deren physische Bindung an Steuergeräteinstanzen (<code>EcuInstance</code>) und Netzwerk-Konnektoren (<code>CommunicationConnector</code>) gemäß den System-Anforderungen <code>TPS_SYST_05007</code> und <code>TPS_SYST_05008</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeDomain</code></strong> (erbt von <code>FibexElement</code>, <code>UploadableDesignElement</code>):\n Zentrale Entität einer logischen Zeitdomäne.\n<ul class=\"fig-list\"><li><code>debounceTime: TimeValue [0..1]</code>: Entprellzeit für Zustandswechsel und Ereignisse.\n</li><li><code>icvFreshnessValueId: PositiveInteger [0..1]</code>: Identifikator des Frischewerts für ICV-Prüfungen.\n</li><li><code>maxProgressionMismatchThreshold: TimeValue [0..1]</code>: Schwellwert für unzulässige Abweichungen im zeitlichen Fortschritt.\n</li><li><code>syncLossTimeout: TimeValue [0..1]</code>: Timeout-Schwelle bis zum Erkennen eines Synchronisationsverlusts.\n</li><li><code>«atpVariation» domainId: PositiveInteger [0..1]</code>: Variantenabhängige eindeutige Kennung der Zeitdomäne.\n</li></ul>\n</li><li><strong><code>GlobalTimeMaster</code></strong> (erbt von <code>Identifiable</code>):\n Zeitgebende Entität innerhalb der Domäne.\n<ul class=\"fig-list\"><li><code>icvSecured: GlobalTimeIcvSupportEnum [0..1]</code>: Status der Integritätsabsicherung (ICV).\n</li><li><code>immediateResumeTime: TimeValue [0..1]</code>: Verzögerungszeit für die Wiederaufnahme der Synchronisationsaussendung.\n</li><li><code>isSystemWideGlobalTimeMaster: Boolean [0..1]</code>: Kennzeichnet die Instanz als fahrzeugweiten Master.\n</li><li><code>syncPeriod: TimeValue [0..1]</code>: Zykluszeit für die periodische Aussendung von Synchronisationsnachrichten.\n</li></ul>\n</li><li><strong><code>GlobalTimeSlave</code></strong> (erbt von <code>Identifiable</code>):\n Zeitnehmende Entität, die auf die Masterzeit synchronisiert wird.\n<ul class=\"fig-list\"><li><code>followUpTimeoutValue: TimeValue [0..1]</code>: Maximale Wartezeit auf eine Follow-Up-PDU.\n</li><li><code>icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Modus der ICV-Verifikation.\n</li><li><code>timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Zukunft.\n</li><li><code>timeLeapHealingCounter: PositiveInteger [0..1]</code>: Zählerschwelle zur Entprellung/Heilung nach Zeitsprüngen.\n</li><li><code>timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert für Zeitsprünge in die Vergangenheit.\n</li></ul>\n</li><li><strong><code>GlobalTimeGateway</code></strong> (erbt von <code>Identifiable</code>):\n Leitet Zeitinformationen zwischen Domänen weiter.\n</li><li><strong><code>CommunicationConnector</code></strong> (erbt von <code>Identifiable</code>):\n Kommunikationsanschluss des Steuergeräts.\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Bestimmt, ob der Anschluss als Weckquelle dient.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert dynamische Zuordnung von Partial Network Clusters.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Typ des PNC-Gateways.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong> (erbt von <code>FibexElement</code>):\n Steuergeräteinstanz im System.\n</li><li><strong><code>NetworkSegmentIdentification</code></strong>:\n<ul class=\"fig-list\"><li><code>networkSegmentId: PositiveInteger [0..1]</code>: Eindeutige Segmentkennung im Netzwerk.\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> (erbt von <code>Identifiable</code>):\n Triggerung der zur Zeitsynchronisation genutzten PDU.\n</li><li><strong><code>AbstractGlobalTimeDomainProps</code></strong>:\n Abstrakte Basisklasse für clusterspezifische Domäneneigenschaften.\n</li><li><strong><code>GlobalTimeCorrectionProps</code></strong>:\n Parameter zur Raten- und Offset-Korrektur.\n<ul class=\"fig-list\"><li><code>allowProviderRateCorrection: Boolean [0..1]</code>: Gibt an, ob Ratenkorrektur durch den Provider erlaubt ist.\n</li><li><code>offsetCorrectionAdaptionInterval: TimeValue [0..1]</code>: Anpassungsintervall für Offset-Korrekturen.\n</li><li><code>offsetCorrectionJumpThreshold: TimeValue [0..1]</code>: Sprungschwellwert für Offset-Korrekturen.\n</li><li><code>providerRateDeviationMax: PositiveInteger [0..1]</code>: Maximale erlaubte Ratenabweichung des Providers.\n</li><li><code>rateCorrectionMeasurementDuration: TimeValue [0..1]</code>: Messdauer für Ratenkorrektur.\n</li><li><code>rateCorrectionsPerMeasurementDuration: PositiveInteger [0..1]</code>: Anzahl der Ratenkorrekturen je Messdauer.\n</li><li><code>rateCorrectionThreshold: PositiveInteger [0..1]</code>: Schwellwert für die Aktivierung der Ratenkorrektur.\n</li><li><code>rateDeviationMeasurementDuration: TimeValue [0..1]</code>: Messintervall zur Bestimmung der Ratenabweichung.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>GlobalTimeIcvSupportEnum</code></strong>: <code>icvSupported</code>, <code>icvNotSupported</code>.\n</li><li><strong><code>GlobalTimeIcvVerificationEnum</code></strong>: <code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code>, <code>icvOptional</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen und Kompositionen</h5>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):\n<ul class=\"fig-list\"><li><code>+globalTimeCorrectionProps 0..1</code>: <code>GlobalTimeCorrectionProps</code>\n</li><li><code>+pduTriggering 0..1</code>: <code>PduTriggering</code>\n</li><li><code>+globalTimeSubDomain 0..*</code>: hierarchische Subdomänen (<code>GlobalTimeDomain</code>)\n</li><li><code>+globalTimeDomainProperty 0..1</code>: <code>AbstractGlobalTimeDomainProps</code>\n</li><li><code>+networkSegmentId 0..1</code>: <code>NetworkSegmentIdentification</code>\n</li><li><code>+gateway 0..*</code>: <code>GlobalTimeGateway</code>\n</li><li><code>+globalTimeMaster 0..1</code>: <code>GlobalTimeMaster</code>\n</li><li><code>+slave 0..*</code>: <code>GlobalTimeSlave</code>\n</li></ul>\n</li><li><code>GlobalTimeGateway</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+host 0..1</code> zu <code>EcuInstance</code>\n</li><li>Assoziation <code>+slave 0..1</code> zu <code>GlobalTimeSlave</code>\n</li><li>Assoziation <code>+master 0..1</code> zu <code>GlobalTimeMaster</code>\n</li></ul>\n</li><li><code>GlobalTimeMaster</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector 0..1</code> zu <code>CommunicationConnector</code>\n</li></ul>\n</li><li><code>GlobalTimeSlave</code>:\n<ul class=\"fig-list\"><li>Assoziation <code>+communicationConnector 0..1</code> zu <code>CommunicationConnector</code>\n</li></ul>\n</li><li><code>EcuInstance</code> aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>):\n<ul class=\"fig-list\"><li><code>+connector *</code>: <code>CommunicationConnector</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Topologie-Setup:</strong>\n<ol class=\"fig-list\"><li>Instanziierung der <code>GlobalTimeDomain</code> mit <code>domainId</code> sowie optionalen <code>AbstractGlobalTimeDomainProps</code>, <code>GlobalTimeCorrectionProps</code> und <code>NetworkSegmentIdentification</code>.\n</li><li>Auflösung des systemweiten Master-Knotens über <code>isSystemWideGlobalTimeMaster == true</code>.\n</li><li>Konfiguration der Kommunikationsanbindung über <code>CommunicationConnector</code> je Master und Slave sowie Zuweisung der PDU-Triggerung über <code>PduTriggering</code>.\n</li></ol>\n</li><li><strong>Periodische Synchronisation &amp; Sicherheitsabsicherung:</strong>\n<ol class=\"fig-list\"><li>Der <code>GlobalTimeMaster</code> triggert im Intervall <code>syncPeriod</code> das Senden einer Zeit-PDU über <code>PduTriggering</code>; falls <code>icvSecured == icvSupported</code>, wird die Nachricht mit einem Integritätsprüfwert (Integrity Check Value) abgesichert.\n</li><li>Bei Two-Step-Verfahren wartet der Empfänger bis zu <code>followUpTimeoutValue</code> auf die Follow-Up-PDU.\n</li><li>Der <code>GlobalTimeSlave</code> prüft eingehende Nachrichten gemäß <code>icvVerification</code> (<code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code> oder <code>icvOptional</code>). Bei erfolgreicher Prüfung und Plausibilisierung gegen <code>timeLeapFutureThreshold</code> und <code>timeLeapPastThreshold</code> (unter Berücksichtigung von <code>timeLeapHealingCounter</code>) wird die lokale Uhr korrigiert.\n</li><li>Phasen- und Frequenzanpassungen erfolgen parametrisiert über <code>GlobalTimeCorrectionProps</code>.\n</li></ol>\n</li><li><strong>Gateway-Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>GlobalTimeGateway</code> empfängt über die zugeordnete <code>GlobalTimeSlave</code>-Rolle die Zeitbasis einer Quell-Domäne.\n</li><li>Weitergabe der Zeit über den internen Bezug auf die zugeordnete <code>GlobalTimeMaster</code>-Rolle zur Einspeisung in eine Ziel-Domäne.\n</li></ol>\n</li><li><strong>Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Bei Ausfall der Synchronisationsnachrichten über <code>syncLossTimeout</code> hinaus wird unter Berücksichtigung von <code>debounceTime</code> Synchronisationsverlust signalisiert. Nachrichten mit fehlerhaftem ICV werden entsprechend der Konfiguration verworfen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Variabilität und Aufteilbarkeit:</strong> Sämtliche Kompositionen von <code>GlobalTimeDomain</code> und <code>EcuInstance</code> sowie das Attribut <code>domainId</code> von <code>GlobalTimeDomain</code> tragen das Stereotyp <code>«atpVariation»</code> bzw. <code>«atpVariation,atpSplitable»</code> und unterstützen damit formale AUTOSAR-Variantenbildung sowie Verteilung über mehrere ARXML-Dateifragmente.\n</li><li><strong>Konsistenzregeln:</strong> Pro Domäne darf maximal ein <code>GlobalTimeMaster</code> aktiv sein (<code>0..1</code>). Ein <code>GlobalTimeGateway</code> koppelt stets einen lokalen Slave mit einem ausgehenden Master.\n</li><li><strong>Sicherheitsmechanismen:</strong> Die Absicherung per Integrity Check Value (ICV) wird über <code>icvSecured</code> am Master, <code>icvVerification</code> am Slave und <code>icvFreshnessValueId</code> an der Domäne konfiguriert.\n</li></ul>"}], "trans": [{"from": "FIG-e2c926fa9d037c42", "to": "FIG-51e2aacff1c22971", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>GlobalTimeDomain</strong>: Attribut <code>followUpTimeoutValue</code> verschoben zu <code>GlobalTimeSlave</code>; Attribut <code>debounceTime: TimeValue [0..1]</code> hinzugefügt; Kardinalität von <code>syncLossTimeout</code> von <code>1</code> auf <code>[0..1]</code> geändert; Komposition <code>+globalTimeDomainProps</code> zu <code>AbstractGlobalTimeDomainProps [0..1]</code> hinzugefügt.\n</li><li><strong>GlobalTimeMaster</strong>: Attribut <code>immediateResumeTime: TimeValue [0..1]</code> hinzugefügt.\n</li><li><strong>GlobalTimeSlave</strong>: Attribute <code>followUpTimeoutValue: TimeValue [0..1]</code>, <code>timeLeapFutureThreshold: TimeValue [0..1]</code>, <code>timeLeapHealingCounter: PositiveInteger [0..1]</code> und <code>timeLeapPastThreshold: TimeValue [0..1]</code> hinzugefügt.\n</li><li><strong>EcuInstance</strong>: Attribute <code>ethSwitchPortGroupDerivation: Boolean [0..1]</code> und <code>v2xSupported: V2xSupportEnum [0..1]</code> hinzugefügt.\n</li><li><strong>PduTriggering</strong>: Ersetzt <code>GeneralPurposePdu</code> / <code>Pdu</code>; Assoziation von <code>GlobalTimeDomain</code> heißt neu <code>+globalTimePduTriggering [0..1]</code>.\n</li><li><strong>AbstractGlobalTimeDomainProps</strong>: Als neue Metaklasse ergänzt und per Komposition <code>+globalTimeDomainProps [0..1]</code> angebunden.\n</li><li><strong>CommunicationCluster</strong>: Assoziation <code>+communicationCluster 0..*</code> von <code>GlobalTimeDomain</code> entfernt.\n</li></ul>"}, {"from": "FIG-51e2aacff1c22971", "to": "FIG-17abf8f3d1a8981c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>CommunicationCluster</strong>: Metaklasse vollständig aus dem Diagramm entfernt.\n</li><li><strong>GlobalTimeDomain</strong>: Attribut <code>syncLossThreshold</code> entfernt; Komposition <code>+globalTimeCorrectionProps [0..1]</code> zur neuen Metaklasse <code>GlobalTimeCorrectionProps</code> ergänzt; Kompositionsrolle <code>+globalTimeDomainProps</code> in <code>+globalTimeDomainProperty [0..1]</code> umbenannt und mit Stereotyp <code>«atpVariation»</code> versehen; Kompositionsrolle <code>+subDomain</code> in <code>+globalTimeSubDomain [0..*]</code> umbenannt und mit Stereotyp <code>«atpVariation»</code> versehen; Assoziationsrolle <code>+globalTimePduTriggering</code> in <code>+pduTriggering [0..1]</code> umbenannt und mit Stereotyp <code>«atpVariation»</code> versehen; Kompositionsrollen <code>+slave 0..*</code>, <code>+gateway 0..*</code> und <code>+globalTimeMaster 0..1</code> (vormals <code>+master 0..1</code>) mit Stereotyp <code>«atpVariation»</code> versehen.\n</li><li><strong>GlobalTimeCorrectionProps</strong>: Als neue Metaklasse mit Attributen <code>offsetCorrectionAdaptionInterval</code>, <code>offsetCorrectionJumpThreshold</code>, <code>rateCorrectionMeasurementDuration</code> und <code>rateCorrectionsPerMeasurementDuration</code> eingeführt.\n</li><li><strong>GlobalTimeMaster</strong>: Kompositionsrolle von <code>GlobalTimeDomain</code> von <code>+master 0..1</code> in <code>+globalTimeMaster 0..1</code> umbenannt.\n</li></ul>"}, {"from": "FIG-17abf8f3d1a8981c", "to": "FIG-9d3ff3647d0c2574", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>CommunicationConnector</strong>: Attribut <code>createEcuWakeupSource: Boolean [0..1]</code> hinzugefügt.\n</li><li><strong>EcuInstance</strong>: Attribut <code>diagnosticAddress: Integer [0..1]</code> entfernt; Attribut <code>pncSynchronousWakeup: Boolean [0..1]</code> hinzugefügt; Assoziation <code>+connector *</code> mit Stereotyp <code>«atpVariation»</code> versehen.\n</li><li><strong>GlobalTimeDomain</strong>: Assoziation <code>+offsetTimeDomain 0..1</code> mit Stereotyp <code>«atpVariation»</code> versehen.\n</li></ul>"}, {"from": "FIG-9d3ff3647d0c2574", "to": "FIG-c7dcf7fc04af5af1", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcuInstance</strong>: Sämtliche spezifischen Kommunikations- und Powermanagement-Attribute (<code>comConfigurationGwTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationTxTimeBase</code>, <code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncPrepareSleepTimer</code>, <code>pncSynchronousWakeup</code>, <code>pnResetTime</code>, <code>sleepModeSupported</code>, <code>v2xSupported</code>, <code>wakeUpOverBusSupported</code>) aus der Klassendarstellung entfernt.\n</li><li><strong>CommunicationConnector</strong>: Attribut <code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code> hinzugefügt.\n</li><li><strong>NetworkSegmentIdentification</strong>: Neue Metaklasse mit Attribut <code>networkSegmentId: PositiveInteger [0..1]</code> eingeführt und über Komposition <code>+networkSegmentId [0..1]</code> an <code>GlobalTimeDomain</code> angebunden.\n</li><li><strong>GlobalTimeDomain</strong>: Stereotyp <code>«atpVariation»</code> an Assoziation <code>+offsetTimeDomain 0..1</code> entfernt.\n</li></ul>"}, {"from": "FIG-c7dcf7fc04af5af1", "to": "FIG-745b7fdd02641762", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>GlobalTimeMaster</strong>: Attribut <code>icvSecured: GlobalTimeIcvSupportEnum [0..1]</code> hinzugefügt.\n</li><li><strong>GlobalTimeSlave</strong>: Attribut <code>icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code> hinzugefügt.\n</li><li><strong>CommunicationConnector</strong>: Attribut <code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> hinzugefügt.\n</li><li><strong>GlobalTimeIcvSupportEnum</strong>: Neues Enumerationselement mit Literalen <code>icvSupported</code> und <code>icvNotSupported</code> ergänzt.\n</li><li><strong>GlobalTimeIcvVerificationEnum</strong>: Neues Enumerationselement mit Literalen <code>icvVerified</code>, <code>icvNotVerified</code>, <code>icvIgnored</code> und <code>icvOptional</code> ergänzt.\n</li><li><strong>GlobalTimeDomain / EcuInstance</strong>: Stereotypen an sämtlichen varianten Kompositionen und Assoziationen (<code>+pduTriggering</code>, <code>+globalTimeSubDomain</code>, <code>+globalTimeDomainProperty</code>, <code>+gateway</code>, <code>+slave</code>, <code>+globalTimeMaster</code>, <code>+connector</code>) von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li></ul>"}, {"from": "FIG-745b7fdd02641762", "to": "FIG-8842564e4be0cbb6", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>GlobalTimeDomain</strong>: Zusätzliche Generalisierung <code>UploadableDesignElement</code> ergänzt; Multiplizität des Attributs <code>domainId</code> von obligatorisch (<code>PositiveInteger</code>) auf optional (<code>PositiveInteger [0..1]</code>) gelockert.\n</li><li><strong>GlobalTimeMaster</strong>: Multiplizitäten der Attribute <code>isSystemWideGlobalTimeMaster</code> und <code>syncPeriod</code> von obligatorisch (<code>Boolean</code> bzw. <code>TimeValue</code>) auf optional (<code>[0..1]</code>) geändert.\n</li><li><strong>GlobalTimeGateway</strong>: Kardinalitäten der Assoziationen <code>+master</code> und <code>+slave</code> von jeweils <code>1</code> auf optional <code>0..1</code> geändert; Kardinalität der Assoziation <code>+host</code> zu <code>EcuInstance</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><strong>GlobalTimeSlave</strong>: Kardinalität der Assoziation <code>+communicationConnector</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li><strong>GlobalTimeMaster</strong>: Kardinalität der Assoziation <code>+communicationConnector</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li></ul>"}, {"from": "FIG-8842564e4be0cbb6", "to": "FIG-4a1b82f4a506c077", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code>: Attribute <code>icvFreshnessValueId: PositiveInteger [0..1]</code> und <code>maxProgressionMismatchThreshold: TimeValue [0..1]</code> hinzugefügt.\n</li><li><code>GlobalTimeDomain</code>: Selbst-Assoziation <code>+offsetTimeDomain 0..1</code> entfernt.\n</li><li><code>GlobalIcvSupportEnum</code>, <code>GlobalTimeIcvVerificationEnum</code>: Stereotyp/Kopfzeile um <code>literals</code> ergänzt (redaktionell).\n</li></ul>"}, {"from": "FIG-4a1b82f4a506c077", "to": "FIG-719015d57d522355", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code>: Attribut <code>domainId</code> mit Stereotyp <code>«atpVariation»</code> versehen.\n</li><li><code>GlobalTimeCorrectionProps</code>: Attribute <code>allowProviderRateCorrection: Boolean [0..1]</code>, <code>providerRateDeviationMax: PositiveInteger [0..1]</code>, <code>rateCorrectionThreshold: PositiveInteger [0..1]</code> und <code>rateDeviationMeasurementDuration: TimeValue [0..1]</code> hinzugefügt.\n</li></ul>"}]};
